import{_ as e,o as r,c as s,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-Jan-09 :: Ceph Testing Weekly","description":"","frontmatter":{"title":"2019-Jan-09 :: Ceph Testing Weekly","date":"2019-01-09T00:00:00.000Z","updated":"2019-01-10T00:00:00.000Z","tags":["Ceph社区动态","测试进展","Pull Request 测试流程","Rook Orchestrator","Ceph版本更新"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-Jan-09_-_-_Ceph_Testing_Weekly.md","filePath":"posts/2019/2019-Jan-09_-_-_Ceph_Testing_Weekly.md","lastUpdated":1780459816000}'),o={name:"posts/2019/2019-Jan-09_-_-_Ceph_Testing_Weekly.md"};function a(l,t,n,p,h,_){return r(),s("div",null,[...t[0]||(t[0]=[i('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年1月（具体日期未提及）</p><p><strong>参会人员</strong>： Yuri, Lea, Christians, Nathan, Astron, Sebastian, Ricardo, Gregory, 等</p><p><strong>会议主题</strong>： Ceph社区动态、测试工作进展、Pull Request (PR) 测试流程讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph社区动态</strong></p><ul><li>Yuri分享了在德国旅行经历，并提及了Ceph社区成员Nathan可能因假期结束而忙碌。</li><li>Christians提到Ceph社区成员Brett和Susan可能对不进行充分测试感到疲倦，希望在下一个版本中加强测试。</li><li>Gregory提到Ceph社区已发布Mimic 13和Luminous，并即将推出Nautilus。</li></ul><p><strong>二、测试工作进展</strong></p><ul><li>Lea与QE团队负责人Mark讨论了Brooke测试流程，并计划编写接口文档供部署者参考。</li><li>Christians提到Rook Orchestrator的测试工作，并询问社区成员是否愿意共享测试资源。</li><li>Astron提到Rook Orchestrator的测试工作，并询问社区成员是否愿意集成SSH-based Orchestrator进行测试。</li><li>Ricardo提到Sousa团队也开发了Orchestrator，但主要用于开发Despot。</li></ul><p><strong>三、Pull Request (PR) 测试流程讨论</strong></p><ul><li>Sebastian询问社区是否有关于测试上游PR的文档或流程。</li><li>Christians提到社区成员Josh正在尝试自动化测试流程。</li><li>Gregory提到社区内部已创建Jenkins作业，用于测试下游PR。</li><li>Astron提到社区内部存在一些测试流程文档，但需要进一步整理和完善。</li><li>Sebastian建议在邮件列表或更高层次的讨论中继续讨论测试流程，并可能需要撰写更多文档。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Lea将继续编写Brooke测试接口文档。</li><li>Christians将继续推动Rook Orchestrator的测试工作。</li><li>Astron将继续探索SSH-based Orchestrator的测试方案。</li><li>Ricardo将继续开发Sousa团队的Orchestrator。</li><li>Sebastian将继续整理和完善PR测试流程文档。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中多次提到Ceph社区成员和项目，如Lea, Christians, Nathan, Astron, Sebastian, Ricardo, Gregory, 等。</li><li>会议中多次提到Ceph社区项目，如Ceph, Rook, Orchestrator, 等。</li><li>会议中多次提到Ceph社区版本，如Mimic, Luminous, Nautilus, 等。</li><li>会议中提到了测试流程和自动化，涉及Brooke, Rook Orchestrator, SSH-based Orchestrator等关键词。</li></ul>',16)])])}const g=e(o,[["render",a]]);export{c as __pageData,g as default};
